async function init() {
 try {
  if (playerConfig.ads.pre_roll.enabled) {
   await showPreRoll();
  } else {
   const { url, type } = await resolveVideo();
   initPlayer(url, type);
  }
 } catch (e) { showError(e.message); }
}
function showPreRoll(){ return Promise.resolve("fixture-pre-ad"); }
function showPauseAd(){ return "fixture-pause-ad"; }
function bindAds(art){
 if (playerConfig.ads.pause.enabled) {
  art.on('pause',()=>showPauseAd());
  art.on('play',()=>closePauseAd());
 }
}
